// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    function testFuzz_property(address randomUser, address rewardToken) public {
        vm.assume(rewardToken != address(0));

        // Act as owner to add a reward token
        vm.prank(c.owner());
        c.addReward(rewardToken);

        // The general rule: after any sequence of operations starting from deployment,
        // owner() must return the address that was set as owner at construction time (address(this) in setUp)
        assertTrue(c.owner() == address(this));
    }
}

